import test from "node:test"
import assert from "node:assert/strict"
import fs from "node:fs"
import os from "node:os"
import path from "node:path"
import { TaskBrowserTabs, readBrowserSources } from "../src/business-evidence/task-pages"
import { EvidenceStore } from "../src/business-evidence/store"
import { captureLocalPageResult } from "../src/business-evidence/executor"
import { evidenceScopeHash } from "../src/business-evidence/content"
import { classifyError } from "../src/security"

// Generated by the real BrowserBridge create/read/guarded-close entry points.
const wire = () => JSON.parse(fs.readFileSync(path.join(__dirname, "../../tests/fixtures/task-tabs-848.json"), "utf8"))

function fixture() {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "cmspark-task-pages-")), recorded = wire()
  const scope = { kind: "chat" as const, threadId: "task-one" }
  const store = new EvidenceStore(root, scope)
  let current = true, closeSuccess = true, capture = true, calls = 0, onClose = () => {}
  const lifecycle = new TaskBrowserTabs({ dataDir: root, threadId: scope.threadId,
    executionId: recorded.context.execution_id, current: () => current,
    execute: async (id, name, params) => {
      if (name === "create_tab") return structuredClone(recorded.create)
      if (name === "get_page_text") return capture ? captureLocalPageResult(root, scope, id, name, structuredClone(recorded.read)) : { success: false, error: "PAGE_READ_FAILED" }
      if (name === "close_tab") {
        calls++
        // Durable source/observation associations must exist before the browser is touched.
        const sources = readBrowserSources(root, scope).data.sources
        assert.equal(sources[0].state, "closing")
        assert.equal(params.__task_tab_cleanup.token, recorded.create.data.task_tab.token)
        assert.equal(params.__task_tab_cleanup.navigation_key, recorded.read.data.provenance.target.navigation_key)
        onClose()
        return closeSuccess ? structuredClone(recorded.close) : { success: false, data: { reason: "FOREGROUND_TAB" } }
      }
      return { success: true }
    } })
  return { root, scope, store, lifecycle, calls: () => calls, stop: () => { current = false },
    beforeCloseReply: (fn: () => void) => { onClose = fn },
    failedClose: () => { closeSuccess = false }, failedRead: () => { capture = false },
    cleanup: () => fs.rmSync(root, { recursive: true, force: true }) }
}

async function openAndRead(f: ReturnType<typeof fixture>) {
  const created = await f.lifecycle.execute("create", "create_tab", { url: "https://example.test/source", active: false })
  assert.equal(created.data.task_tab, undefined, "private creation identity never reaches the model")
  return f.lifecycle.execute("read", "get_page_text", { tabId: created.data.id })
}

test("successful completion archives task/run/source/evidence before closing; evidence survives reload", async () => {
  const f = fixture()
  try {
    const read = await openAndRead(f)
    assert.deepEqual(await f.lifecycle.finish(true), { closed: 1, retained: 0 })
    assert.equal(f.calls(), 1)
    const sources = readBrowserSources(f.root, f.scope).data.sources
    assert.equal(sources[0].thread_id, f.scope.threadId)
    assert.equal(sources[0].execution_id, wire().context.execution_id)
    assert.equal(sources[0].state, "closed")
    assert.equal(sources[0].url, "https://example.test/source")
    assert.equal(sources[0].evidence[0].tool_call_id, "read")
    const reloaded = readBrowserSources(f.root, f.scope, read.data.observation_id)
    assert.equal(reloaded.data.observation.content, wire().read.data.text)
    assert.equal(reloaded.data.observation.id, sources[0].observation_ids[0])
    assert.equal(JSON.stringify(sources).includes("token=private"), false)
    assert.equal(readBrowserSources(f.root, { kind: "chat", threadId: "other" }).data.sources.length, 0)
    assert.equal(readBrowserSources(f.root, { kind: "chat", threadId: "other" }, read.data.observation_id).success, false)
  } finally { f.cleanup() }
})

test("explicit release closes immediately and is not repeated at run completion", async () => {
  const f = fixture()
  try {
    await openAndRead(f)
    assert.equal((await f.lifecycle.execute("release", "close_tab", { tabId: 7 })).success, true)
    assert.equal(f.calls(), 1)
    assert.deepEqual(await f.lifecycle.finish(true), { closed: 0, retained: 0 })
  } finally { f.cleanup() }
})

test("explicitly kept and existing user tabs are not automatic candidates", async () => {
  const f = fixture()
  try {
    await f.lifecycle.execute("kept", "create_tab", { url: "https://example.test/source", keep_open: true })
    await f.lifecycle.execute("read", "get_page_text", { tabId: 7 })
    await f.lifecycle.execute("user-read", "get_page_text", { tabId: 99 })
    assert.deepEqual(await f.lifecycle.finish(true), { closed: 0, retained: 0 })
    assert.equal(f.calls(), 0)
  } finally { f.cleanup() }
})

test("failed, interrupted, superseded and no-longer-observed runs never auto-close", async () => {
  for (const mode of ["failed-run", "superseded", "failed-read", "changed-page"] as const) {
    const f = fixture()
    try {
      await openAndRead(f)
      if (mode === "superseded") f.stop()
      if (mode === "failed-read") { f.failedRead(); await f.lifecycle.execute("reread", "get_page_text", { tabId: 7 }) }
      if (mode === "changed-page") await f.lifecycle.execute("navigate", "navigate", { tabId: 7, url: "https://example.test/next" })
      await f.lifecycle.finish(mode !== "failed-run")
      assert.equal(f.calls(), 0, mode)
    } finally { f.cleanup() }
  }
})

test("missing capture and failed close retain pages and never write a successful close", async () => {
  const f = fixture()
  try {
    await f.lifecycle.execute("create", "create_tab", { url: "https://example.test/source" })
    f.failedRead(); await f.lifecycle.execute("read", "get_page_text", { tabId: 7 })
    assert.deepEqual(await f.lifecycle.finish(true), { closed: 0, retained: 1 })
    assert.equal(f.calls(), 0)
    assert.equal(readBrowserSources(f.root, f.scope).data.sources[0].state, "retained")
  } finally { f.cleanup() }
  const next = fixture()
  try {
    await openAndRead(next); next.failedClose()
    assert.deepEqual(await next.lifecycle.finish(true), { closed: 0, retained: 1 })
    const source = readBrowserSources(next.root, next.scope).data.sources[0]
    assert.equal(source.state, "retained"); assert.equal(source.reason, "FOREGROUND_TAB")
    assert.equal(source.closed_at, undefined)
  } finally { next.cleanup() }
})

test("archive write failure prevents even explicit task-tab close", async () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "cmspark-tab-store-fault-")), blocked = path.join(root, "file")
  fs.writeFileSync(blocked, "not a directory")
  let closed = 0
  const run = new TaskBrowserTabs({ dataDir: blocked, threadId: "one", executionId: wire().context.execution_id,
    current: () => true, execute: async (_id, name) => {
      if (name === "create_tab") return wire().create
      closed++; return wire().close
    } })
  try {
    const created = await run.execute("create", "create_tab", { url: "https://example.test/source" })
    assert.equal(created.data.task_tab_lifecycle.reason, "SOURCE_ARCHIVE_FAILED")
    const close = await run.execute("close", "close_tab", { tabId: 7 })
    assert.equal(close.success, false); assert.equal(closed, 0)
  } finally { fs.rmSync(root, { recursive: true, force: true }) }
})

test("model-authored guard metadata is stripped from existing-tab operations", async () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "cmspark-tab-forgery-"))
  let args: any
  const run = new TaskBrowserTabs({ dataDir: root, threadId: "one", executionId: wire().context.execution_id,
    current: () => true, execute: async (_id, _name, input) => { args = input; return { success: true } } })
  try {
    await run.execute("close", "close_tab", { tabId: 99, __task_tab_cleanup: { token: "forged" } })
    assert.deepEqual(args, { tabId: 99 })
  } finally { fs.rmSync(root, { recursive: true, force: true }) }
})

test("a missing durable close receipt stays uncertain even when the browser acknowledged closure", async () => {
  const f = fixture()
  try {
    await openAndRead(f)
    f.beforeCloseReply(() => {
      const filename = path.join(f.root, "business-evidence-v1", evidenceScopeHash(f.scope) + ".json")
      fs.mkdirSync(filename + ".tmp-" + process.pid)
    })
    const result = await f.lifecycle.execute("close", "close_tab", { tabId: 7 })
    assert.equal(result.success, true)
    assert.equal(result.data.task_tab_lifecycle.state, "close_acknowledgement_unrecorded")
    assert.equal(readBrowserSources(f.root, f.scope).data.sources[0].state, "closing")
    assert.equal(f.calls(), 1)
  } finally { f.cleanup() }
})

test("retained pages and unavailable source lookup are recoverable outcomes", () => {
  for (const message of ["TASK_TAB_RETAINED: USER_OR_OTHER_TASK_ADOPTED", "BROWSER_SOURCE_STORE_UNAVAILABLE", "BROWSER_SOURCE_NOT_FOUND"]) {
    assert.equal(classifyError(message, { toolName: "close_tab" }), "recoverable")
  }
})
